import defaults, { DatepickerOptions,DatepickerDate,DatepickerDecade } from './Default';
import {
    copyDate,
    createDate,
    createElement,
    deepCopy,
    deepMerge,
    getDecade,
    getEl,
    getParsedDate,
    getWordBoundaryRegExp,
    insertAfter,
    isDateBigger,
    isDateSmaller,
    isSameDate,
} from './common/utils';
import DatepickerBody from './DatepickerBody';
import DatepickerNav from './DatepickerNav';
import DatepickerButtons from './DatepickerButtons';
import DatepickerTime from './DatepickerTime';
import DatepickerKeyboard from './datepickerKeyboard';
import withEvents from './common/withEvents';
import consts,{DatepickerView} from './common/consts';
import {DateLike,CellType} from './common/types';
import './DatepickerVars.scss';
import './Datepicker.scss';

// File-level variables for global container management
let $datepickersContainer: HTMLElement | string = '';
let $datepickerOverlay: HTMLElement | string = '';
let containerBuilt = false;
const baseTemplate = '' +
    '<i class="datepicker--pointer"></i>' +
    '<div class="datepicker--navigation"></div>' +
    '<div class="datepicker--content"></div>';

interface FocusDateOptions {
    viewDateTransition?: boolean;
}

export default class Datepicker extends withEvents(Object) {
    static defaults: DatepickerOptions = defaults;
    static defaultGlobalContainerId = 'datepicker-global-container';

    // Element references
    $el: HTMLElement | HTMLInputElement;
    $datepicker!: HTMLElement;
    $customContainer!: HTMLElement | false;
    $altField!: HTMLInputElement | null;
    $container!: HTMLElement;
    $content!: HTMLElement;
    $pointer!: HTMLElement;
    $nav!: HTMLElement;
    $timepicker?: HTMLElement;
    $buttons?: HTMLElement;

    // Options and Locale
    opts!: DatepickerOptions;
    locale: any;
    // State properties
    inited = false;
    visible = false;
    inFocus = false;
    viewDate!: Date;
    focusDate: Date | false = false;
    initialReadonly : string | null = '';
    customHide: ((params: any) => void) | false = false;
    currentView: DatepickerView = consts.days;
    selectedDates:   DatepickerDate[] = [];
    disabledDates: Set<any> = new Set();
    isDestroyed = false;
    views: Record<string, any> = {};
    keys: any[] = [];
    rangeDateFrom: any = '';
    rangeDateTo: any = '';
    timepickerIsActive = false;
    treatAsInline!: boolean;
    elIsInput = false;
    minDate: Date | false = false;
    maxDate: Date | false = false;
    hideAnimation = false;
    lastSelectedDate: Date | boolean | undefined = false;
    // Sub-components
    nav!: any;
    timepicker?: any;
    buttons?: any;
    keyboardNav?: any;

    private _onTransitionEnd?: (e?: TransitionEvent) => void;
    viewIndexes = [consts.days, consts.months, consts.years];

    static buildGlobalContainer(id: string) {
        containerBuilt = true;
        $datepickersContainer = createElement({ className: id, id });
        getEl('body')!.appendChild($datepickersContainer as HTMLElement);
    }

    constructor(el: string | HTMLElement, opts?: Partial<DatepickerOptions>) {
        super();
        this.$el = getEl(el) as HTMLElement;

        if (!this.$el) return;

        this.$datepicker = createElement({ className: 'datepicker' });
        this.opts = deepMerge({}, defaults, opts);
        this.$customContainer = this.opts.container ? getEl(this.opts.container) as HTMLElement : false;
        this.$altField = this.opts.altField 
            ? (getEl(this.opts.altField) as HTMLInputElement) 
            : null;

        if (this.$el.nodeName === 'INPUT') {
            this.elIsInput = true;
        }
        this.selectedDates = [];
        const rawSelected = this.opts.selectedDates;

        if (Array.isArray(rawSelected)) {
            rawSelected.forEach(d => {
                const parsed = createDate(d);
                if (parsed instanceof Date) this.selectedDates.push(parsed);
            });;
        }

        let initialViewDate: Date;

        if (this.selectedDates.length > 0) {
            initialViewDate = new Date((this.selectedDates[0] as Date).getTime());
        } else if (this.opts.startDate) {
            const start = createDate(this.opts.startDate);
            initialViewDate = start instanceof Date ? start : new Date();
        } else {
            initialViewDate = new Date();
        }

        this.viewDate = initialViewDate;
        this.currentView = this.opts.view!;
        this.elIsInput = this.$el.nodeName === 'INPUT';
        this.treatAsInline = !!(this.opts.inline || !this.elIsInput);
        this.initialReadonly = this.$el.getAttribute('readonly');
        this.init();
    }

    init() {
        let {
            opts,
            treatAsInline,
            opts: {
                inline,
                isMobile,
                selectedDates,
                keyboardNav,
                onlyTimepicker
            }
        } = this;
        let $body = getEl('body');


        let shouldBuildGlobalContainer =
            (!containerBuilt || (containerBuilt && $datepickersContainer && !$body?.contains($datepickersContainer as Node)))
            && !inline
            && this.elIsInput
            && !this.$customContainer;

        if (shouldBuildGlobalContainer) {
            Datepicker.buildGlobalContainer(Datepicker.defaultGlobalContainerId);
        }

        this.$container = (this.$customContainer || $datepickersContainer || $body) as HTMLElement;
        if (isMobile && !$datepickerOverlay && !treatAsInline) {
            this._createMobileOverlay();
        }

        this._handleLocale();
        this._bindSubEvents();
        this._createMinMaxDates();
        this._limitViewDateByMaxMinDates();
        if (this.selectedDates.length > 0) {
            const initialDates = [...this.selectedDates];
            this.selectedDates = []; 
            this.selectDate(initialDates, { silent: true });
        }

               // Bind events if it's an input
        if (this.elIsInput) {
            if (!this.opts.inline) this._bindEvents();
            if (this.opts.keyboardNav && !this.opts.onlyTimepicker) {
                this.keyboardNav = new DatepickerKeyboard({ dp: this, opts: this.opts });
            }
        }

        // Build UI components
        if (this.treatAsInline) {
            this._createComponents();
        }

        if (this.opts.visible && !this.treatAsInline) {
            this.show();
        }
    }

    _createMobileOverlay() {
        $datepickerOverlay = createElement({ className: 'datepicker-overlay' });
        ($datepickersContainer as HTMLElement).appendChild($datepickerOverlay as HTMLElement);
    }
  
    _createComponents() {
        let {
            opts,
            treatAsInline,
            opts: {
                inline,
                buttons,
                timepicker,
                position,
                classes,
                onlyTimepicker,
                isMobile,
            }
        } = this;
        let dp = this;

        this._buildBaseHtml();

        if (this.elIsInput) {
            if (!inline) {
                this._setPositionClasses(position!);
            }
        }

        if (inline || !this.elIsInput) {
            this.$datepicker.classList.add('-inline-');
        }

        if (classes) {
            this.$datepicker.classList.add(...classes.split(' '));
        }

        if (onlyTimepicker) {
            this.$datepicker.classList.add('-only-timepicker-');
        }

        if (isMobile && !treatAsInline) {
            this._addMobileAttributes();
        }

        this.views[this.currentView] = new DatepickerBody({
            dp,
            type: this.currentView,
            opts
        });

        this.nav = new DatepickerNav({ dp, opts });

        if (timepicker) {
            this._addTimepicker();
        }

        if (buttons) {
            this._addButtons();
        }

        this.$content.appendChild(this.views[this.currentView].$el);
        this.$nav.appendChild(this.nav.$el);

        if (this.selectedDates.length) {
            this.selectDate(this.selectedDates, { silent: true });
        }
    }

    _destroyComponents() {
        for (let view in this.views) {
            this.views[view].destroy();
        }
        this.views = {};
       // Use optional chaining or explicit checks
        if (this.nav && typeof this.nav.destroy === 'function') {
            this.nav.destroy();
        }
        
        if (this.timepicker && typeof this.timepicker.destroy === 'function') {
            this.timepicker.destroy();
        }
        
        if (this.buttons && typeof this.buttons.destroy === 'function') {
            this.buttons.destroy();
        }
    }

    _addMobileAttributes() {
        ($datepickerOverlay as HTMLElement).addEventListener('click', this._onClickOverlay);

        this.$datepicker.classList.add('-is-mobile-');
        this.$el.setAttribute('readonly', 'true');
    }

    _removeMobileAttributes() {
        ($datepickerOverlay as HTMLElement).removeEventListener('click', this._onClickOverlay);

        this.$datepicker.classList.remove('-is-mobile-');

        if (this.initialReadonly === null) {
            this.$el.removeAttribute('readonly');
        }
    }

    _createMinMaxDates() {
        let { minDate, maxDate } = this.opts;

        this.minDate = minDate ? createDate(minDate) : false;
        this.maxDate = maxDate ? createDate(maxDate) : false;
    }

    _addTimepicker() {
        this.$timepicker = createElement({ className: 'datepicker--time' });
        this.$datepicker.appendChild(this.$timepicker);
        this.timepicker = new DatepickerTime({ dp: this, opts: this.opts });
        this.$timepicker.appendChild(this.timepicker.$el);
    }

    _addButtons() {
        this.$buttons = createElement({ className: 'datepicker--buttons' });
        this.$datepicker.appendChild(this.$buttons);
        this.buttons = new DatepickerButtons({ dp: this, opts: this.opts });
        this.$buttons.appendChild(this.buttons.$el);
    }

    _bindSubEvents() {
        this.on(consts.eventChangeSelectedDate, this._onChangeSelectedDate);
        this.on(consts.eventChangeFocusDate, this._onChangeFocusedDate);
        this.on(consts.eventChangeTime, this._onChangeTime);
    }

    _buildBaseHtml() {
        let { inline } = this.opts;

        // Debugging line
        if (!this.$container) {
            console.error('Datepicker: $container is undefined. Check init() logic.');
            return; 
        }

        if (this.elIsInput) {
            if (!inline) {
                this.$container.appendChild(this.$datepicker);
            } else {
                insertAfter(this.$datepicker, this.$el);
            }
        } else {
            this.$el.appendChild(this.$datepicker);
        }

        this.$datepicker.innerHTML = baseTemplate;

        this.$content = getEl('.datepicker--content', this.$datepicker) as HTMLElement;
        this.$pointer = getEl('.datepicker--pointer', this.$datepicker) as HTMLElement;
        this.$nav = getEl('.datepicker--navigation', this.$datepicker) as HTMLElement;
    }

    _handleLocale() {
        let { locale, dateFormat, firstDay, timepicker, onlyTimepicker, timeFormat, dateTimeSeparator } = this.opts;
        this.locale = deepCopy(locale!);

        if (dateFormat) {
            this.locale.dateFormat = dateFormat;
        }
        if (timeFormat !== undefined && timeFormat !== '') {
            this.locale.timeFormat = timeFormat;
        }

        let { timeFormat: timeFormatValidated } = this.locale;

        if (firstDay !== '') {
            this.locale.firstDay = firstDay as number;
        }

        if (timepicker && typeof dateFormat !== 'function') {
            let separator = timeFormatValidated ? dateTimeSeparator : '';
            this.locale.dateFormat = [this.locale.dateFormat, (timeFormatValidated ? timeFormatValidated : '')].join(separator!);
        }

        if (onlyTimepicker && typeof dateFormat !== 'function') {
            this.locale.dateFormat = this.locale.timeFormat;
        }
    }

    _setPositionClasses(pos: string | Function) {
        if (typeof pos === 'function') {
            this.$datepicker.classList.add('-custom-position-');
            return;
        }

        const posArr = pos.split(' ');
        let main = posArr[0],
            sec = posArr[1],
            classes = `datepicker -${main}-${sec}- -from-${main}-`;

        this.$datepicker.classList.add(...classes.split(' '));
    }

    _bindEvents() {
        if (this.opts.showEvent !== 'none') {
            this.$el.addEventListener(this.opts.showEvent!, this._onFocus);
        }
        // this.$el.addEventListener(this.opts.showEvent!, this._onFocus);
        this.$el.addEventListener('blur', this._onBlur);
        this.$datepicker.addEventListener('mousedown', this._onMouseDown);
        this.$datepicker.addEventListener('mouseup', this._onMouseUp);
        window.addEventListener('resize', this._onResize);
    }

    _limitViewDateByMaxMinDates() {
        let { viewDate, minDate, maxDate } = this;

        if (maxDate && isDateBigger(viewDate, maxDate)) {
            this.setViewDate(maxDate);
        }
        if (minDate && isDateSmaller(viewDate, minDate)) {
            this.setViewDate(minDate);
        }
    }
    
    formatDate = (dateParam: DatepickerDate, format: string): any => {
        // console.log('formatDate =' + dateParam);
        // console.log('formatDate format=' + format);
         const date = createDate(dateParam);
        if (!(date instanceof Date)) return;
    

        let result = format;
        const locale = this.locale;
        const parsedDate = getParsedDate(date);
        const decade = getDecade(date);
        const replacer = Datepicker.replacer;

        const seconds = date.getSeconds();
        const fullSeconds = seconds.toString().padStart(2, '0');

        const formats: Record<string, string | number> = {
            yyyy: parsedDate.year,
            yy: parsedDate.year.toString().slice(-2),

            MMMM: locale.months[parsedDate.month],
            MMM: locale.monthsShort[parsedDate.month],
            MM: parsedDate.fullMonth,
            M: parsedDate.month + 1,

            dd: parsedDate.fullDate,
            d: parsedDate.date,
            
            EEEE: locale.days[parsedDate.day],
            E: locale.daysShort[parsedDate.day],

            // 24-Hour tokens
            HH: parsedDate.fullHours, // e.g., 13
            H: parsedDate.hours,      // e.g., 13

            // 12-Hour tokens
            hh: parsedDate.fullHours12, // e.g., 01
            h: parsedDate.hours12,      // e.g., 1

            // Minutes
            mm: parsedDate.fullMinutes,
            m: parsedDate.minutes,

                // SECONDS (Added)
            ss: fullSeconds,
            s: seconds,

            aa: parsedDate.dayPeriod,
            AA: parsedDate.dayPeriod.toUpperCase(),

            yyyy1: decade[0],
            yyyy2: decade[1],
            T: date.getTime(),
        };
        const sortedKeys = Object.keys(formats).sort((a, b) => b.length - a.length);

        for (let key of sortedKeys) {
            result = replacer(result, getWordBoundaryRegExp(key), formats[key]);
        }

        return result;
    }

    next = () => {
        let { year, month } = this.parsedViewDate;

        switch (this.currentView) {
            case consts.days:
                this.setViewDate(new Date(year, month + 1, 1));
                break;
            case consts.months:
                this.setViewDate(new Date(year + 1, month, 1));
                break;
            case consts.years:
                this.setViewDate(new Date(year + 10, 0, 1));
                break;
        }
    }

    prev = () => {
        let { year, month } = this.parsedViewDate;

        switch (this.currentView) {
            case consts.days:
                this.setViewDate(new Date(year, month - 1, 1));
                break;
            case consts.months:
                this.setViewDate(new Date(year - 1, month, 1));
                break;
            case consts.years:
                this.setViewDate(new Date(year - 10, 0, 1));
                break;
        }
    }

    down(date?: Date) {
        this._handleUpDownActions(date, 'down');
    }

    up(date?: Date) {
        this._handleUpDownActions(date, 'up');
    }

    selectDate(date: any, params: { updateTime?: boolean, silent?: boolean } = {}): Promise<void> {
        let { currentView, parsedViewDate, selectedDates } = this;
        let { updateTime, silent } = params;
        let {
            moveToOtherMonthsOnSelect,
            moveToOtherYearsOnSelect,
            multipleDates,
            range,
            autoClose,
            onBeforeSelect,
        } = this.opts;
        let selectedDaysLen = selectedDates.length;
        let newViewDate: Date | undefined;

        // Handle array of dates (recursive)
        if (Array.isArray(date)) {
            date.forEach((d) => {
                this.selectDate(d, params);
            });

            return new Promise((resolve) => {
                setTimeout(resolve);
            });
        }

        date = createDate(date);

        if (!(date instanceof Date)) return Promise.resolve();
       
         if (onBeforeSelect && !silent && !onBeforeSelect({date, datepicker: this})) {
            return Promise.resolve();
        }

        // Checks if selected date is out of current month or decade
        // If so, change `viewDate`
        if (currentView === consts.days) {
            if (date.getMonth() !== parsedViewDate.month && moveToOtherMonthsOnSelect) {
                newViewDate = new Date(date.getFullYear(), date.getMonth(), 1);
            }
        }

         if (currentView === consts.years) {
            if (date.getFullYear() !== parsedViewDate.year && moveToOtherYearsOnSelect) {
                newViewDate = new Date(date.getFullYear(), 0, 1);
            }
        }

        if (newViewDate) {
            this.setViewDate(newViewDate);
        }
        // Selection Logic
        if (multipleDates && !range) {
            if (selectedDaysLen === multipleDates) return Promise.resolve();
            if (!this._checkIfDateIsSelected(date)) {
                selectedDates.push(date);
            }
        } else if (range) {
            switch (selectedDaysLen) {
                case 1:
                    selectedDates.push(date);
                    if (!this.rangeDateTo) {
                        this.rangeDateTo = date;
                    }

                    if (isDateBigger(this.rangeDateFrom as Date, this.rangeDateTo)) {
                        this.rangeDateTo = this.rangeDateFrom as Date;
                        this.rangeDateFrom = date;
                    }
                    this.selectedDates = [this.rangeDateFrom as Date, this.rangeDateTo as Date];
                    break;
                case 2:
                    this.selectedDates = [date];
                    this.rangeDateFrom = date;
                    this.rangeDateTo = '';
                    break;
                default:
                    this.selectedDates = [date];
                    this.rangeDateFrom = date;
            }
        } else {
            this.selectedDates = [date];
        }

        // Trigger Internal Events
        this.trigger(consts.eventChangeSelectedDate, {
            action: consts.actionSelectDate,
            silent: params?.silent,
            date,
            updateTime
        });
        this._updateLastSelectedDate(date);

        // Auto Close Logic
        if (autoClose && !this.timepickerIsActive && this.visible) {
            if (!multipleDates && !range) {
                this.hide();
            } else if (range && selectedDaysLen === 1) {
                this.hide();
            }
        }

        return new Promise((resolve) => {
            setTimeout(resolve);
        });
    }

    unselectDate(date: DatepickerDate): boolean | undefined {
        const normalizedDate = createDate(date);
        if (!(normalizedDate instanceof Date)) return;

        if (!Array.isArray(this.selectedDates)) {
            // If it's a single date and matches, clear it
            if (isSameDate(this.selectedDates, normalizedDate)) {
                this.selectedDates = [];
                this.rangeDateFrom = '';
                this.rangeDateTo = '';
                return true;
            }
            return false;
        }

        const selected = this.selectedDates;

        // 3. Find and remove the date
        return selected.some((curDate, i) => {
            // createDate is used here to ensure curDate is a Date object for comparison
            const curDateObj = createDate(curDate);
            if (!(curDateObj instanceof Date)) return false;

            if (isSameDate(curDateObj, normalizedDate)) {
                selected.splice(i, 1);

                if (selected.length === 0) {
                    this.rangeDateFrom = '';
                    this.rangeDateTo = '';
                    this._updateLastSelectedDate(false);
                } else {
                    this.rangeDateTo = '';
                    const firstDate = createDate(selected[0]);
                    this.rangeDateFrom = firstDate instanceof Date ? firstDate : '';
                    const lastDate = createDate(selected[selected.length - 1]);
                    this._updateLastSelectedDate(lastDate instanceof Date ? lastDate : false);
                }

                this.trigger(consts.eventChangeSelectedDate, {
                    action: consts.actionUnselectDate,
                    date: normalizedDate
                });

                return true;
            }
            return false;
        });      
    }

    replaceDate = (selectedDate: Date, newDate: Date) => {
        const foundDate = this.selectedDates.find((d) => {
            return isSameDate(d, selectedDate, this.currentView);
        });

        if (!foundDate) return;

        let index = this.selectedDates.indexOf(foundDate);

        if (index < 0) return;

         if (isSameDate(this.selectedDates[index], newDate, this.currentView)) {
            return;
        }

        this.selectedDates[index] = newDate;

         this.trigger(consts.eventChangeSelectedDate, {
            action: consts.actionSelectDate,
            date: newDate,
            updateTime: true
        });
        this._updateLastSelectedDate(newDate);
    }    
    
    clear(params: { silent?: boolean } = {}) {
        this.selectedDates = [];
        this.rangeDateFrom = false;
        this.rangeDateTo = false;
        this.lastSelectedDate = false;

        this.trigger(consts.eventChangeSelectedDate, { action: consts.actionUnselectDate, silent: params.silent });

        return new Promise((resolve) => {
            setTimeout(resolve);
        });
    }

    show() {
        let { onShow, isMobile } = this.opts;
        this._cancelScheduledCall();

        if (!this.visible && !this.hideAnimation) {
            this._createComponents();
        }

        this.setPosition(this.opts.position!);

        this.$datepicker.classList.add('-active-');
        this.visible = true;

        if (onShow) {
            this._scheduleCallAfterTransition(onShow);
        }

        if (isMobile) {
            this._showMobileOverlay();
        }
    }

    hide() {
        let { onHide, isMobile } = this.opts;
        let hasTransition = (this as any)._hasTransition();

        this.visible = false;
        this.hideAnimation = true;

        this.$datepicker.classList.remove('-active-');

        if (this.customHide) {
            (this.customHide as Function)();
        }

        if (this.elIsInput) {
            this.$el.blur();
        }

        this._scheduleCallAfterTransition((isAnimationCompleted: boolean) => {
            if (
                !this.customHide &&
                ((isAnimationCompleted && hasTransition) ||
                    (!isAnimationCompleted && !hasTransition))
            ) {
                this._finishHide();
            }
            onHide && onHide(isAnimationCompleted);
        });

        if (isMobile) {
            ($datepickerOverlay as HTMLElement).classList.remove('-active-');
        }
    }

    _finishHide = () => {
        this.hideAnimation = false;
        this._destroyComponents();
        this.$container.removeChild(this.$datepicker);
    }

    setPosition = (position: string | Function | undefined, isViewChange = false) => {
        const posStr = position || this.opts.position;

        if (typeof posStr === 'function') {
            this.customHide = posStr({
                $datepicker: this.$datepicker,
                $target: this.$el,
                $pointer: this.$pointer,
                isViewChange,
                done: this._finishHide
            });
            return;
        }

        let { isMobile } = this.opts;

        let vpDims = this.$el.getBoundingClientRect(),
            dims = this.$el.getBoundingClientRect(),
            $dpOffset = this.$datepicker.offsetParent as HTMLElement,
            $elOffset = (this.$el as HTMLElement).offsetParent as HTMLElement,
            selfDims = this.$datepicker.getBoundingClientRect(),
            pos = (posStr as string).split(' '),
            top: number, left: number,
            scrollTop = window.scrollY,
            scrollLeft = window.scrollX,
            offset = this.opts.offset!,
            main = pos[0],
            secondary = pos[1];

        if (isMobile) {
            this.$datepicker.style.cssText = 'left: 50%; top: 50%';
            return;
        }

        if ($dpOffset === $elOffset && $dpOffset !== document.body) {
            dims = {
                top: (this.$el as HTMLElement).offsetTop,
                left: (this.$el as HTMLElement).offsetLeft,
                width: vpDims.width,
                height: (this.$el as HTMLElement).offsetHeight
            } as DOMRect;

            scrollTop = 0;
            scrollLeft = 0;
        }

        if ($dpOffset !== $elOffset && $dpOffset !== document.body) {
            let dpOffsetDims = $dpOffset.getBoundingClientRect();

            dims = {
                top: vpDims.top - dpOffsetDims.top,
                left: vpDims.left - dpOffsetDims.left,
                width: vpDims.width,
                height: vpDims.height
            } as DOMRect;

            scrollTop = 0;
            scrollLeft = 0;
        }

        top = 0;
        left = 0;

        switch (main) {
            case 'top':
                top = dims.top - selfDims.height - offset;
                break;
            case 'right':
                left = dims.left + dims.width + offset;
                break;
            case 'bottom':
                top = dims.top + dims.height + offset;
                break;
            case 'left':
                left = dims.left - selfDims.width - offset;
                break;
        }

        switch (secondary) {
            case 'top':
                top = dims.top;
                break;
            case 'right':
                left = dims.left + dims.width - selfDims.width;
                break;
            case 'bottom':
                top = dims.top + dims.height - selfDims.height;
                break;
            case 'left':
                left = dims.left;
                break;
            case 'center':
                if (/left|right/.test(main)) {
                    top = dims.top + dims.height / 2 - selfDims.height / 2;
                } else {
                    left = dims.left + dims.width / 2 - selfDims.width / 2;
                }
        }

        this.$datepicker.style.cssText = `left: ${left + scrollLeft}px; top: ${top + scrollTop}px`;
    }

    _setInputValue = () => {
        let { opts, $altField, locale: { dateFormat } } = this,
            { altFieldDateFormat, altField } = opts;

        if (altField && $altField) {
            $altField.value = this._getInputValue(altFieldDateFormat!);
        }

        // (this.$el as HTMLInputElement).value = this._getInputValue(dateFormat!);
        if (this.elIsInput && !this.opts.inline) {
            // If you want to NEVER show it regardless of inline status, 
            // you can simply comment out the line below.
            (this.$el as HTMLInputElement).value = this._getInputValue(dateFormat!);
        }
        this.$el.dispatchEvent(new Event('change'));
    }

    _getInputValue = (dateFormat: string | Function) => {
        let { selectedDates, opts } = this,
            { multipleDates, multipleDatesSeparator } = opts;

        if (!selectedDates.length) return '';

        let formatIsFunction = typeof dateFormat === 'function';

        let value = formatIsFunction
            ? (dateFormat as Function)(multipleDates ? selectedDates : selectedDates[0])
            : selectedDates.map((date) => {
                return this.formatDate(date, dateFormat as string);
            });

        value = formatIsFunction
            ? value
            : value.join(multipleDatesSeparator);

        return value;
    }

    _triggerOnSelect() {
        let dates: Date[] = [],
            formattedDates: string[] = [],
            datepicker = this,
            { selectedDates, locale, opts: { onSelect, multipleDates, range } } = datepicker,
            isMultiple = multipleDates || range,
            formatIsFunction = typeof locale.dateFormat === 'function';

        if (selectedDates.length) {
            dates = selectedDates
                .map(d => createDate(d))     
                .filter((d): d is Date => !!d)
                .map(d => copyDate(d));

            formattedDates = formatIsFunction
            ? (multipleDates
                ? (locale.dateFormat as any)(dates)
                : dates.map(date => (locale.dateFormat as any)(date)))
            : dates.map(date => this.formatDate(date, locale.dateFormat as string) as string);
        }

        if (onSelect) {
            onSelect({
                date: isMultiple ? dates : (dates[0] || null), 
                formattedDate: isMultiple ? formattedDates : (formattedDates[0] || ''),
                datepicker
            });
        }
    }

    _checkIfDateIsSelected(date: Date, type: DatepickerView = consts.days): boolean {
        return this.selectedDates.some(selectedDate => {
            return isSameDate(date, selectedDate, type);
        });
    }
    // _checkIfDateIsSelected = (date: Date, cellType: 'days' | 'months' | 'years' = 'days'): Date | false => {     
    //         let alreadySelectedDate: Date | boolean = false;


    //         this.selectedDates.some((selectedDate: DatepickerDate) => {
    //             const same = isSameDate(date, selectedDate, cellType);
    //            if (same) {
    //                 const normalized = createDate(selectedDate);
    //                 if (normalized instanceof Date) {
    //                     alreadySelectedDate = normalized;
    //                 }
    //             }
    //             return same;
    //         });
    //      return alreadySelectedDate;
    // }

    _handleAlreadySelectedDates(alreadySelectedDate: Date, cellDate: Date) {
        let { selectedDates, rangeDateFrom, rangeDateTo } = this;
        let { range, toggleSelected } = this.opts;
        let selectedDatesLen = selectedDates.length;
        let isFunc = typeof toggleSelected === 'function';
        let shouldToggle = isFunc ? (toggleSelected as Function)({ datepicker: this, date: cellDate }) : toggleSelected;
        let datesAreSame = Boolean(range && selectedDatesLen === 1 && alreadySelectedDate);
        let cellDateCopy = datesAreSame ? copyDate(cellDate) : cellDate;

        if (range) {
            if (!shouldToggle) {
                if (selectedDatesLen !== 2) {
                    this.selectDate(cellDateCopy);
                }
                if (selectedDatesLen === 2 && isSameDate(rangeDateFrom as Date, rangeDateTo as Date)) {
                    return;
                }
            }
        }

        if (shouldToggle) {
            this.unselectDate(cellDateCopy);
        } else {
            this._updateLastSelectedDate(datesAreSame ? cellDateCopy : alreadySelectedDate);
        }
    }

    _handleUpDownActions(date: Date | undefined, dir: string) {
        let maxViewIndex = 2;
        let minViewIndex = 0;

        const d = createDate(date || this.focusDate || this.viewDate);
        if (!(d instanceof Date)) return;

        // Get the index of the current view to calculate the next one
        const currentViewIndex = this.viewIndexes.indexOf(this.currentView);
        let nextView = dir === 'up' ? currentViewIndex + 1 : currentViewIndex - 1;

        if (nextView > maxViewIndex) nextView = maxViewIndex;
        if (nextView < minViewIndex) {
            // If we are at the lowest view (days) and click "down", we select the date
            this.selectDate(d);
            return;
        }

        this.setViewDate(new Date(d.getFullYear(), d.getMonth(), 1));
        // Call the newly defined method
        this.setCurrentView(this.viewIndexes[nextView]);
    }

    _scheduleCallAfterTransition = (cb: Function) => {
        this._cancelScheduledCall();

        cb && cb(false);

        this._onTransitionEnd = () => {
            cb && cb(true);
        };

        this.$datepicker.addEventListener('transitionend', this._onTransitionEnd as any, { once: true });
    }

    _cancelScheduledCall = () => {
        this.$datepicker.removeEventListener('transitionend', this._onTransitionEnd as any);
    }

    setViewDate = (date: DatepickerDate) => {
      
        const parsed = createDate(date);
        if (!(parsed instanceof Date)) {
            return; 
        }

        if (isSameDate(parsed, this.viewDate)) return;
        let oldViewDate = this.viewDate;
        this.viewDate = parsed;

        let {onChangeViewDate} = this.opts;
        if (onChangeViewDate) {
            let {month, year} = this.parsedViewDate;
            onChangeViewDate({
                month,
                year,
               decade: this.curDecade as DatepickerDecade
            });
        }
        this.trigger(consts.eventChangeViewDate, date, oldViewDate);
    }

    setFocusDate = (
        date?: DatepickerDate | null, 
        params: { viewDateTransition?: boolean } = {}
    ) => {
        let resultDate: Date | false = false;

        if (date) {
            const normalized = createDate(date);
            if (!(normalized instanceof Date)) return;
            resultDate = normalized;
        }

        this.focusDate = resultDate;

        this.trigger(consts.eventChangeFocusDate, resultDate, params);
    }

    setCurrentView = (
        view: DatepickerView, 
        params: { silent?: boolean } = {}
        ): void => {
            // 2. Safety check using the allowed indexes
            if (!this.viewIndexes.includes(view)) return;

            this.currentView = view;

            if (this.elIsInput && this.visible) {
                this.setPosition(undefined, true);
            }

            // Trigger inner event
            this.trigger(consts.eventChangeCurrentView, view);

            // 3. Handle view initialization
            if (!this.views[view]) {
                const newView = new DatepickerBody({
                    dp: this,
                    opts: this.opts,
                    type: view
                });
                
                this.views[view] = newView;

                if (this.shouldUpdateDOM) {
                    this.$content.appendChild(newView.$el);
                }
            }

            // 4. Trigger user-defined callback
            if (this.opts.onChangeView && !params.silent) {
                this.opts.onChangeView(view);
            }
    }

    _updateLastSelectedDate = (date: DatepickerDate | boolean): void => {
        let result: Date | boolean;
        if (typeof date === 'boolean') {
            result = date;
        } else {
            const normalized = createDate(date);
            result = normalized instanceof Date ? normalized : false;
        }
        this.lastSelectedDate = result;
        this.trigger(consts.eventChangeLastSelectedDate, date);
    }

    getCell(cellDate: DateLike, cellType: CellType = consts.day as CellType): HTMLElement | null {
        const parsedCellDate = createDate(cellDate);

        if (!(parsedCellDate instanceof Date)) {
            return null;
        }

        const { year, month, date } = getParsedDate(parsedCellDate);

        const yearQuery = `[data-year="${year}"]`;
        const monthQuery = `[data-month="${month}"]`;
        const dayQuery = `[data-date="${date}"]`;

        // Map cell types to their specific CSS attribute selectors
        const resultQuery: Record<string, string> = {
            [consts.day]: `${yearQuery}${monthQuery}${dayQuery}`,
            [consts.month]: `${yearQuery}${monthQuery}`,
            [consts.year]: `${yearQuery}`,
        };

        // Safety check: Can only find cells if the current view exists
        const currentViewInstance = this.views[this.currentView];
        if (!currentViewInstance || !currentViewInstance.$el) {
            return null;
        }

        return currentViewInstance.$el.querySelector(resultQuery[cellType]);
    }

    destroy = (): void => {
        if (this.isDestroyed) return;
         const { showEvent, isMobile } = this.opts;
        this._unbindEvents(); 
        this._destroyComponents();

        // Remove the datepicker element from the DOM
        if (this.$datepicker && this.$datepicker.parentNode) {
            this.$datepicker.parentNode.removeChild(this.$datepicker);
        }

        // Reset initial attributes if necessary
        if (this.elIsInput && this.initialReadonly === null) {
            this.$el.removeAttribute('readonly');
        }

        // 1. Remove from DOM
        const parent = this.$datepicker?.parentNode;
        if (parent && this.$datepicker) {
            parent.removeChild(this.$datepicker);
        }

        // 2. Unbind Events
        if (showEvent) {
            this.$el.removeEventListener(showEvent, this._onFocus);
        }

        this.$el.removeEventListener('blur', this._onBlur);
        window.removeEventListener('resize', this._onResize);

        if (isMobile) {
            this._removeMobileAttributes();
        }

        // 3. Destroy sub-components
        if (this.keyboardNav) {
            this.keyboardNav.destroy();
        }

        // 4. Nullify properties (casting to 'any' for cleanup if class properties are strict)
        (this as any).views = {};
        (this as any).nav = null;
        (this as any).timepicker = null;
        (this as any).buttons = null;

        (this as any).$datepicker = null;
        (this as any).opts = {} as any;
        (this as any).$customContainer = null;

        (this as any).viewDate = null;
        (this as any).focusDate = null;
        this.selectedDates = [];
        (this as any).rangeDateFrom = null;
        (this as any).rangeDateTo = null;
         this.isDestroyed = true;
    }

    update = (newOpts: Partial<DatepickerOptions> = {},   params: { silent?: boolean } = {}): void => {
        const prevOpts = deepMerge({}, this.opts) as DatepickerOptions;
        const { silent } = params;

        deepMerge(this.opts, newOpts);

        const { timepicker, buttons, range, selectedDates, isMobile } = this.opts;
        const shouldUpdateDOM = this.visible || this.treatAsInline;

        this._createMinMaxDates();
        this._limitViewDateByMaxMinDates();
        this._handleLocale();

        if (selectedDates) {
            this.selectedDates = [];
            this.selectDate(selectedDates, { silent });
        }

        if (newOpts.view) {
            this.setCurrentView(newOpts.view, { silent });
        }

        this._setInputValue();

        // Handle Range Logic
        if (prevOpts.range && !range) {
            this.rangeDateTo = false;
            this.rangeDateFrom = false;
        } else if (!prevOpts.range && range) {
            if (this.selectedDates.length) {
                this.rangeDateFrom = this.selectedDates[0];
                this.rangeDateTo = this.selectedDates[1];
            }
        }

        // Handle Timepicker Logic
        if (prevOpts.timepicker && !timepicker) {
            if (shouldUpdateDOM) this.timepicker.destroy();
            this.timepicker = false;
            this.$timepicker?.parentNode?.removeChild(this.$timepicker);
        } else if (!prevOpts.timepicker && timepicker) {
            this._addTimepicker();
        }

        // Handle Buttons Logic
        if (!prevOpts.buttons && buttons) {
            this._addButtons();
        } else if (prevOpts.buttons && !buttons) {
            this.buttons.destroy();
            this.$buttons?.parentNode?.removeChild(this.$buttons);
        } else if (shouldUpdateDOM && prevOpts.buttons && buttons) {
            this.buttons.clearHtml().render();
        }

        // Handle Mobile Logic
        if (!prevOpts.isMobile && isMobile) {
            if (!this.treatAsInline && !$datepickerOverlay) {
                this._createMobileOverlay();
            }
            this._addMobileAttributes();
            if (this.visible) this._showMobileOverlay();
        } else if (prevOpts.isMobile && !isMobile) {
            this._removeMobileAttributes();
            if (this.visible && $datepickerOverlay) {
                ($datepickerOverlay as HTMLElement).classList.remove('-active-');
                if (typeof this.opts.position !== 'function') {
                    this.setPosition(this.opts.position!);
                }
            }
        }

        if (!shouldUpdateDOM) return;

        this.nav.update();
        this.views[this.currentView].render();
        if (this.currentView === consts.days) {
            this.views[this.currentView].renderDayNames();
        }
    }

    /**
     * Disables or enables dates
     * @param dates - Date or array of dates to handle
     * @param _enable - If true, enables the date; if false (default), disables it
     */
    disableDate = (dates: DateLike | DateLike[], _enable?: boolean): void => {
        const datesToHandle: DateLike[] = Array.isArray(dates) ? dates : [dates];

        datesToHandle.forEach((date) => {
            const trueDate = createDate(date);
            if (!(trueDate instanceof Date)) return;

            // Determine method based on whether we are enabling or disabling
            const method: 'delete' | 'add' = _enable ? 'delete' : 'add';
            
            // Formatting to 'yyyy-MM-dd' ensures unique keys in the Set
            const formatted = this.formatDate(trueDate, 'yyyy-MM-dd');
            
            // Update the internal state
            (this.disabledDates as Set<string>)[method](formatted);

            // Find the cell in the current view to trigger a re-render
            const cell = this.getCell(trueDate, this.currentViewSingular as CellType);

            // Use type assertion (as any) if adpCell is a custom property added to the element
            if (cell && (cell as any).adpCell) {
                (cell as any).adpCell.render();
            }
        });
    }

    /**
     * Enables previously disabled dates
     * @param dates - Date or array of dates to enable
     */
    enableDate = (dates: DateLike | DateLike[]): void => {
        this.disableDate(dates, true);
    }

    isDateDisabled = (date: DateLike): boolean => {
        const trueDate = createDate(date);
        // If the date is invalid, we return false (or handle as needed)
        if (!(trueDate instanceof Date)) {
            return false;
        }
        return (this.disabledDates as Set<string>).has(this.formatDate(trueDate, 'yyyy-MM-dd'));
    }
   
    _showMobileOverlay() {
        ($datepickerOverlay as HTMLElement).classList.add('-active-');
    }

   _hasTransition(): boolean {
        // 1. Get the transition-duration string (e.g., "0.3s, 0.1s")
        const transition = window.getComputedStyle(this.$datepicker).getPropertyValue('transition-duration');
        
        // 2. Split into individual property durations
        const props = transition.split(', ');

        // 3. Sum up the values. 
        // We explicitly type the accumulator 'sum' as a number.
        const totalDuration = props.reduce((sum: number, item: string) => {
            return parseFloat(item) + sum;
        }, 0);

        return totalDuration > 0;
    }

    isOtherMonth = (date: Date): boolean => {
        const { month } = getParsedDate(date);
        const { month: viewMonth } = getParsedDate(this.viewDate);
        return month !== viewMonth;
    }

    /**
     * Checks if the provided date belongs to a different year than the current view date
     * @param date - The date to check
     * @returns {boolean} - True if the years are different
     */
    isOtherYear = (date: DateLike): boolean => {
        const nativeDate = createDate(date);
        if (!(nativeDate instanceof Date)) return false;
        const { year } = getParsedDate(nativeDate);

        // parsedViewDate should be a property on the class containing {year, month, date, etc.}
        return year !== this.parsedViewDate.year;
    }

    isOtherDecade = (date: Date): boolean => {
        const { year } = getParsedDate(date);
        const [start, end] = getDecade(this.viewDate);
        return year < start || year > end;
    }

    _onChangeSelectedDate = ({silent}: any) => {
        setTimeout(() => {
            this._setInputValue();
            if (this.opts.onSelect && !silent) {
                this._triggerOnSelect();
            }
        });
    }
    
    _onChangeFocusedDate = (date: Date | null, { viewDateTransition }: FocusDateOptions = {}): void => {
        if (!date) return;

        let shouldPerformTransition = false;

        if (viewDateTransition) {
            shouldPerformTransition = this.isOtherMonth(date) || 
                                    this.isOtherYear(date) || 
                                    this.isOtherDecade(date);
        }

        if (shouldPerformTransition) {
            this.setViewDate(date);
        }

        if (this.opts.onFocus) {
            this.opts.onFocus({ datepicker: this, date });
        }
    }

    _onChangeTime = ({ hours, minutes }:{ hours: number, minutes: number }) => {
        const today = new Date();
        const { lastSelectedDate, opts: { onSelect } } = this;
        
        // 1. Create a working date object. 
        // If lastSelectedDate is a Date, we copy it; if false/null, we use today.
        let targetDate: Date = (lastSelectedDate instanceof Date) 
            ? new Date(lastSelectedDate.getTime()) 
            : today;

        // 2. Get the cell. We cast the element to access custom plugin properties.
        const $cell = this.getCell(targetDate, this.currentViewSingular as CellType) as HTMLElement & { adpCell?: any };
        const cell = $cell?.adpCell;

        // 3. Early exit if the time change lands on a disabled date
        if (cell?.isDisabled) return;

        targetDate.setHours(hours);
        targetDate.setMinutes(minutes);

        if (!(lastSelectedDate instanceof Date)) {
            // If no date was selected yet, select this new time at targetDate
            this.selectDate(targetDate);
        } else {
            // If a date was already selected, update its time
            // We update the original reference or replace it depending on your architecture
            // lastSelectedDate.setHours(hours);
            // lastSelectedDate.setMinutes(minutes);        
            this._setInputValue();
            if (onSelect) {
                this._triggerOnSelect();
            }
        }
    }
 
   _onFocus = () => {
        if (!this.visible) {
            this.show();
        }
    }
  
    _onBlur = () => {
        if (!this.inFocus && this.visible && !this.opts.isMobile) {
            this.hide();
        }
    }

     _onMouseDown = () => {
        this.inFocus = true;
    }

    _onMouseUp = () => {
        this.inFocus = false;
        this.$el.focus();
    }

    _onResize = () => {
        if (this.visible && typeof this.opts.position !== 'function') {
           this.setPosition(this.opts.position!);
        }
    }

    _onClickOverlay = () => {
        if (this.visible) {
            this.hide();
        }
    }

    /**
     * Returns all dates that currently should be shown in the calendar based on the view type.
     * @param {DatepickerView} viewType - The current view (days, months, or years).
     * @returns {Date[]} - An array of dates to be rendered.
     */
    getViewDates = (viewType: DatepickerView = consts.days as DatepickerView): Date[] => {
        // getDatesFunction returns a function that takes the datepicker instance as an argument
        const getDates = DatepickerBody.getDatesFunction(viewType);
        
        // Return the array of dates generated for this instance
        return getDates(this);
    }

    get shouldUpdateDOM() {
        return this.visible || this.treatAsInline;
    }

    get parsedViewDate() {
        return getParsedDate(this.viewDate);
    }

     get currentViewSingular() {
        return this.currentView.slice(0, -1);
    }

    get curDecade() {
        return getDecade(this.viewDate);
    }

    get viewIndex() {
        return this.viewIndexes.indexOf(this.currentView);
    }

    get isFinalView() {
        return this.currentView === consts.years;
    }

    get hasSelectedDates() {
        return this.selectedDates.length > 0;
    }

    get isMinViewReached() {
        return this.currentView === this.opts.minView || this.currentView === consts.days;
    }


    isWeekend = (day: number): boolean => {
        const { weekends } = this.opts;
        return weekends!.includes(day);
    }

    getClampedDate = (date : Date) => {
        let {minDate, maxDate} = this,
            newDate = date;

        if (maxDate && isDateBigger(date, maxDate)) {
            newDate = maxDate;
        } else if (minDate && isDateSmaller(date, minDate)) {
            newDate = minDate;
        }

        return newDate;
    }

    static replacer(str: string, reg: RegExp, data: string | number): string {
        return str.replace(reg, (match: string, p1: string, p2: string, p3: string) => {
            return p1 + data + p3;
        });
    }

    _unbindEvents() {
        this.$el.removeEventListener(this.opts.showEvent!, this._onFocus);
        this.$el.removeEventListener('blur', this._onBlur);
        this.$datepicker.removeEventListener('mousedown', this._onMouseDown);
        this.$datepicker.removeEventListener('mouseup', this._onMouseUp);
        window.removeEventListener('resize', this._onResize);
    }
}